/**
 * A compact index of a RUNNING node's API, refreshed from its live OpenAPI document.
 *
 * It writes `api-index.md` and `schema-index.md`, deliberately not `http-api.md` and `schemas.md` — those are
 * generated by `ainize-node/scripts/docs-gen.mjs` from the code itself, and a test there fails when they drift
 * from it. Two tools writing one file is not a merge conflict waiting to happen; it is a file whose contents
 * depend on which tool ran last, and both of these overwrote each other for a while.
 *
 * The two answer different questions and both are worth having. `docs-gen` answers *what does the code promise*
 * — every validation rule, every default, derived by probing the schema, recorded nowhere else. This answers
 * *what is that node serving right now*, which no amount of reading the source can tell you.
 *
 *   node scripts/sync-api-docs.mjs [OpenAPI URL or file]
 */
import { readFileSync, writeFileSync } from 'node:fs';
const input = process.argv[2] ?? 'https://ainize.ai/api/openapi.json';
let spec;
if (/^https?:/.test(input)) {
  const response = await fetch(input);
  if (!response.ok) throw new Error(`OpenAPI returned ${response.status}`);
  spec = await response.json();
} else spec = JSON.parse(readFileSync(input, 'utf8'));
if (!spec.openapi || !spec.paths || !spec.components?.schemas) throw new Error('Expected an OpenAPI document');
const clean = value => String(value ?? '').replace(/\s+/g, ' ').replaceAll('|', '\\|').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const short = value => clean(value).split(/(?<=\.)\s/)[0];
const type = s => s.$ref ? s.$ref.split('/').at(-1) : s.enum ? s.enum.map(String).join(', ') : s.type === 'array' ? `array of ${type(s.items ?? {})}` : s.type ?? (s.oneOf || s.anyOf ? 'union (see OpenAPI)' : 'object');
const api = [
  '# API index',
  '',
  'Every route a **running** node answers, read from its own [OpenAPI document](/api/openapi.json) — so this is what that deployment serves, not what the source promises. For the full contract, with every parameter, body and validation rule, see the [HTTP API reference](./http-api.md).',
  '',
  'Refreshed with `node scripts/sync-api-docs.mjs <OpenAPI URL or file>`.',
  '',
  'Use JSON unless an endpoint specifies multipart upload or streaming. Operator sessions and teaching keys are separate credentials. For model SDK authentication and `/v1`, see [Call the model](../how-to/call-the-model.md).',
  '',
];
for (const [path, item] of Object.entries(spec.paths)) {
  for (const [method, op] of Object.entries(item)) {
    if (!['get', 'post', 'put', 'patch', 'delete', 'options', 'head'].includes(method)) continue;
    const security = op.security ?? spec.security ?? [];
    const auth = security.length ? security.map(s => Object.keys(s).join(' + ') || 'none').join(' or ') : 'No security scheme declared; check required headers below.';
    api.push(`## \`${method.toUpperCase()} ${path}\``, '', short(op.summary || op.description), '', `Auth: ${auth} Responses: ${Object.keys(op.responses ?? {}).map(s => '\`'+s+'\`').join(', ')}.`, '');
    const parameters = [...(item.parameters ?? []), ...(op.parameters ?? [])];
    if (parameters.length) {
      api.push('| Parameter | In | Required | Type |', '|---|---|---|---|');
      for (const p of parameters) api.push(`| \`${p.name}\` | ${p.in} | ${p.required ? 'yes' : 'no'} | ${clean(type(p.schema ?? {}))} |`);
      api.push('');
    }
    if (op.requestBody) api.push(`Body: ${Object.keys(op.requestBody.content ?? {}).join(', ')}${op.requestBody.required ? ' (required)' : ''}. See OpenAPI for fields.`, '');
  }
}
writeFileSync(new URL('../docs/en/reference/api-index.md', import.meta.url), api.join('\n').trimEnd()+'\n');
const schemas = [
  '# Schema index',
  '',
  'Reusable shapes as a **running** node declares them, from its [OpenAPI document](/api/openapi.json). For the full definitions, with nested constraints and unions, see [Schemas](./schemas.md).',
  '',
];
for (const [name, schema] of Object.entries(spec.components.schemas)) {
  schemas.push(`## \`${name}\``, '', short(schema.description), '');
  if (schema.properties) {
    schemas.push('| Field | Type | Required |', '|---|---|---|');
    for (const [field, s] of Object.entries(schema.properties)) schemas.push(`| \`${field}\` | ${clean(type(s))} | ${schema.required?.includes(field) ? 'yes' : 'no'} |`);
    schemas.push('');
  } else schemas.push(clean(type(schema)), '');
}
writeFileSync(new URL('../docs/en/reference/schema-index.md', import.meta.url), schemas.join('\n').trimEnd()+'\n');
